import {createRequire} from 'node:module';
import {mkdir,writeFile} from 'node:fs/promises';
const require=createRequire('C:/Users/user/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright/package.json');const {chromium}=require('playwright');
const browser=await chromium.launch({channel:'msedge',headless:true});const context=await browser.newContext({viewport:{width:1440,height:1000}});const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));const results=[];const phase=process.argv[2]??'before';const dir='../../review/review-assets/audit-20261003';await mkdir(dir,{recursive:true});
await page.goto('http://localhost:4173');await page.waitForSelector('.todo-row');
const checkbox=page.locator('.todo-row input').first();await checkbox.focus();await page.keyboard.press('Space');results.push({name:'TO DO 완료 체크 후 키보드 포커스 유지',pass:await page.locator('.todo-row input').first().evaluate(e=>e===document.activeElement)});
await page.setViewportSize({width:390,height:844});const middle=page.locator('[data-grip]').nth(1);await middle.focus();await page.keyboard.press('ArrowLeft');results.push({name:'좁은 화면 메모 왼쪽 방향키는 위 순서 이동',pass:await page.locator('.note').first().evaluate(e=>e.dataset.note==='n2')});
for(const width of [1440,1024,768,390,320]){await page.setViewportSize({width,height:1000});await page.screenshot({path:`${dir}/${phase}-${width}.png`,fullPage:true});results.push({name:`${width}px 가로 넘침 없음`,pass:await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)});}
await page.locator('#mail-open').click();results.push({name:'메일 팝업 접근 가능한 이름',pass:await page.getByRole('dialog',{name:/미회신 메일/}).count()===1});await page.keyboard.press('Escape');results.push({name:'메일 Escape 닫기·포커스 복귀',pass:await page.locator('#mail-open').evaluate(e=>e===document.activeElement)});
await page.goto('http://localhost:4173/?state=empty');results.push({name:'빈 일정·TO DO·메모 안내',pass:await page.locator('.empty').count()===4});await page.locator('#mail-open').click();results.push({name:'빈 메일 안내',pass:await page.getByText('미회신 예시 메일이 없어요.').count()===1});await page.keyboard.press('Escape');
await page.locator('footer a').click();results.push({name:'빈 상태 링크',pass:page.url().endsWith('?state=empty')});
await page.addInitScript(()=>Object.defineProperty(navigator,'clipboard',{value:{writeText:async()=>{throw Error('denied');}},configurable:true}));await page.goto('http://localhost:4173');await page.locator('#mail-open').click();await page.locator('#copy-draft').click();results.push({name:'복사 실패 시 수동 복사 안내',pass:(await page.locator('#status').textContent()).includes('직접 복사')});
await page.screenshot({path:`${dir}/${phase}-mail.png`,fullPage:true});
await context.close();const blocked=await browser.newContext();await blocked.addInitScript(()=>{Storage.prototype.setItem=()=>{throw new DOMException('blocked','QuotaExceededError');};});const p=await blocked.newPage();await p.goto('http://localhost:4173');await p.locator('#add-todo').click();await p.getByLabel('할 일',{exact:true}).fill('저장 오류 검수');await p.getByRole('button',{name:'저장',exact:true}).click();results.push({name:'저장 실패 안내·현재 화면 편집 반영',pass:(await p.locator('#status').textContent()).includes('저장할 수 없어요')&&await p.getByText('저장 오류 검수',{exact:true}).count()===1});await blocked.close();
const report={phase,results,errors};await writeFile(`${dir}/${phase}-results.json`,JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));await browser.close();if(results.some(r=>!r.pass)||errors.length)process.exitCode=1;
